36|
37|  struct msg_parse msg;
38|  struct edns_data edns;
39|  memset(&msg, 0, sizeof(struct msg_parse));
40|  memset(&edns, 0, sizeof(edns));
41|  if (parse_packet(pkt, &msg, reg) != LDNS_RCODE_NOERROR) {    
42|    goto out;
